qs.append(Q(9,1,1,'Crossover coordinates versus fitness','Real-coded crossover of P₁=2 and P₂=6 generates C₁=0.5(P₁+P₂), C₂=1.5P₁−0.5P₂ and C₃=−0.5P₁+1.5P₂. All candidates are feasible. Retain the two highest-fitness children, first for J(x)=x and separately for K(x)=−(x−1)². Which retained sets are correct?', ['J: {4,8}; K: {0,4}.','J: {4,8}; K: {4,8}.','J: {0,4}; K: {0,4}.','J: {0,8}; K: {4,8}.'],['Children are 4,0,8. J ranks 8>4>0, while K values −9,−1,−49 rank 0>4>8.','The J result is right, but maximizing a function does not always mean maximizing its input coordinate.','The K result is right, but J(x)=x selects the two largest coordinates.','For J this skips the second-best child 4, and for K it retains the worst child 8.'],[C(39,'Week 9 Q1, parent values, three crossover formulas and unspecified maximization objective','P1=2,P2=6; children4,0,8; explanation selects4,8 for a maximization problem without specifying the fitness function.','equation','conflict')],'Crossover computes candidate coordinates. Selection ranks their specified fitness, not their coordinates unless the fitness increases accordingly.',assumptions=['Both stated objectives are maximized separately; all three children satisfy constraints; no elitist parent retention or stochastic selection is added.'],steps=['C₁=0.5×8=4; C₂=3−3=0; C₃=−1+9=8.','J values at 4,0,8 are 4,0,8, so retain {4,8}.','K values are −9,−1,−49, so retain {0,4}.'],formulas=[F('C₁=(P₁+P₂)/2; C₂=1.5P₁−0.5P₂; C₃=−0.5P₁+1.5P₂; J(x)=x; K(x)=−(x−1)²',{'C₁':('midpoint child','dimensionless'),'C₂':('first extrapolated child','dimensionless'),'C₃':('second extrapolated child','dimensionless'),'P₁':('first parent coordinate','dimensionless'),'P₂':('second parent coordinate','dimensionless'),'x':('candidate coordinate','dimensionless'),'J':('first supplied fitness','dimensionless'),'K':('second supplied fitness','dimensionless')},['Feasible children; maximize stated fitness.'])],qtype='numerical',difficulty='medium',conflict={'issue':'Original maximization prompt omits the objective, so candidate coordinates alone do not determine fitness order.','resolution':'Two explicit objective functions show when the printed retained set applies and when it changes.','method':'Evaluate all three crossover formulas, then evaluate each supplied fitness at every child.'},angles=['all_crossover_children','fitness_premise','counterexample_to_coordinate_ranking']))
qs.append(Q(9,2,2,'Binary code versus decoded real value','A six-bit unsigned chromosome uses endpoint-inclusive mapping x=1+15D/63, with integer code D from 0 to 63. Which code and six-bit string represent the real value x=11 exactly?', ['D=42, string 101010','D=43, string 101011','D=46, string 101110','D=11, string 001011'],['D=(11−1)×63/15=42, and 42=32+8+2.','43 decodes to 1+645/63≈11.2381, not exactly 11.','46 results from approximately omitting the lower-end offset; it decodes to about 11.9524.','This confuses the real variable with its integer chromosome code; D=11 decodes to about 3.619.'],[C(39,'Week 9 Q2, six-bit range and linear mapping calculation','11=1+((16−1)/(2⁶−1))D; D=42.','equation')],'The integer chromosome code is 42, while its decoded real variable is 11; these are different representations.',assumptions=['Unsigned binary, most significant bit first; both range endpoints represented; no Gray coding.'],steps=['Six bits give integer codes 0 through 63.','Solve 11−1=15D/63 to obtain D=42.','42=32+8+2 gives bits101010.'],formulas=[F('x=a+(b−a)D/(2ⁿ−1); D=(x−a)(2ⁿ−1)/(b−a)',{'x':('decoded real variable','dimensionless'),'a':('lower endpoint,1','dimensionless'),'b':('upper endpoint,16','dimensionless'),'D':('unsigned integer chromosome code','dimensionless'),'n':('number of bits,6','bits')},['Endpoint-inclusive uniform mapping; x is exactly representable here.'])],qtype='numerical',angles=['integer_code','binary_representation','endpoint_denominator']))
grid='Use x=column increasing right and y=row increasing downward. S=(0,0), W₁=(0,1), W₂=(2,4), G=(5,5). Blocked cells are {(1,1),(2,1),(2,2),(4,2),(2,3),(3,4)}. Count unit moves as length L, every entered blocked cell as one collision N, and changes between consecutive nonzero move directions as turns T. Use C=L+10N+T and fitness F=1/(1+C). '
gridform=F('C=L+αN+βT; F=1/(1+C)',{'C':('dimensionless penalized path cost','dimensionless'),'L':('number of unit grid moves','dimensionless grid steps'),'α':('collision penalty weight,10','cost per collision'),'N':('number of entered blocked cells','collisions'),'β':('turn penalty weight,1','cost per turn'),'T':('direction changes between actual moves','turns'),'F':('fitness','dimensionless')},['Grid steps and penalties normalized to dimensionless costs; α=10,β=1; no diagonal moves.'])
qs.append(Q(9,3,3,'Horizontal-first grid fitness',grid+'Decode S→W₁→W₂→G by moving horizontally first and then vertically on each segment. Which (L,N,T,F) is obtained?', ['(10,5,4,1/65)','(10,4,4,1/55)','(10,6,4,1/75)','(10,5,0,1/61)'],['The route enters five blocked cells and makes four direction changes, giving C=10+50+4=64.','This omits one of the five collisions, reducing the denominator incorrectly by10.','This counts every obstacle in the grid, including (4,2), which the route does not enter.','This drops all four turn penalties, although the motion sequence changes direction four times.'],[C(40,'Week 9 Q3, six-by-six grid, blue waypoint cells, red blocked cells and fitness working','Waypoints(0,1),(2,4); obstacles(1,1),(2,1),(2,2),(4,2),(2,3),(3,4); source gives L10,Nobs5,Nturn4,C64,F1/65.','figure')],'The chromosome’s route must be decoded before evaluating obstacle and turn penalties; counting all map obstacles is not the path collision count.',assumptions=['The complete grid and coordinate convention are transcribed into the stem; boundary waypoints are not double-counted as entries; blocked cells are penalized rather than preventing decoding.'],steps=['Move directions are D,R,R,D,D,D,R,R,R,D, where D means increasing y.','Entered blocked cells are (1,1),(2,1),(2,2),(2,3),(3,4).','There are 10 moves and 4 direction changes.','C=10+10×5+4=64; F=1/65.'],formulas=[gridform],qtype='algorithm_trace',difficulty='medium',angles=['exact_grid','decoded_cells','collision_count','turns','fitness']))
qs.append(Q(9,4,4,'Decode order counterfactual',grid+'Now decode each segment of S→W₁→W₂→G vertically first and then horizontally. Which (L,N,T,F) is obtained?', ['(10,0,3,1/14)','(10,5,4,1/65)','(10,1,3,1/24)','(10,0,4,1/15)'],['The vertical-first route avoids all six blocked cells and changes direction three times, so C=13.','This repeats the horizontal-first result without decoding the changed intermediate cells.','The vertical-first route does not enter (3,4) or any other blocked cell; the extra collision is unsupported.','This adds a turn at W₁ even though the direction before and after that waypoint is the same.'],[C(40,'Week 9 Q3 grid and Q4 movement-order explanation','Q4: horizontal-first versus vertical-first may traverse different intermediate cells and change collision count while Manhattan distance remains the same.','figure')],'Changing movement order preserves the Manhattan length of each segment but can change collisions and turns on the concatenated path.',assumptions=['Same grid, chromosome, weights and counting rules; ignore zero-length submoves and do not count a waypoint itself as a turn.'],steps=['Visited route: (0,0),(0,1),(0,2),(0,3),(0,4),(1,4),(2,4),(2,5),(3,5),(4,5),(5,5).','Move directions D,D,D,D,R,R,D,R,R,R give 10 moves and 3 changes.','No entered cell is blocked, so N=0.','C=10+0+3=13; F=1/14.'],formulas=[gridform,F('L_segment=|x₂−x₁|+|y₂−y₁|',{'L_segment':('segment unit-move length','grid steps'),'x₁':('segment start column','grid coordinate'),'x₂':('segment end column','grid coordinate'),'y₁':('segment start row','grid coordinate'),'y₂':('segment end row','grid coordinate')},['Axis-aligned monotone decoding between each waypoint pair.'])],qtype='algorithm_trace',difficulty='medium',angles=['decoder_counterfactual','collision_variation','turn_boundary','same_length']))
qs.append(Q(9,5,5,'Persistent sequence memory','A robot receives one sensor vector at a time. Earlier measurements matter, but past vectors are not concatenated into the current input. Which mechanism explicitly carries a learned internal summary from one time step to the next?', ['An RNN/LSTM whose recurrent state is retained across the sequence.','An MLP applied independently to only the current sensor vector.','An RNN/LSTM whose recurrent state is reset before every individual measurement.','A feedforward model given only an unordered mean of all measurements so far.'],['The retained recurrent state can encode history and temporal order.','With only the current vector and no state, this MLP does not receive earlier observations.','Resetting on every sample discards the cross-time state that supplies sequence memory.','An unordered mean can summarize past values but loses their ordering and is not a learned recurrent state.'],[C(41,'Week 9 Q5, sequence-dependent robot decision and RNN/LSTM explanation','RNN/LSTM associates with sequences of sensor data where previous observations can influence the current decision.')],'The chosen mechanism retains state. This does not claim that a feedforward or convolutional model supplied with an explicit history window could never use temporal information.',assumptions=['Sequential inference with state preserved within a sequence; comparisons use exactly the stated inputs and reset behavior.'],angles=['sequence_memory','reset_boundary','feedforward_history_qualification']))
qs.append(Q(9,6,6,'Network parameter accounting','A fully connected network has 6 input features, 16 hidden neurons and 4 output neurons, with one bias for each hidden and output neuron. Which triple gives (input-to-hidden weights only, all weights excluding biases, all trainable weights plus biases)?', ['(96,160,180)','(112,180,180)','(96,96,112)','(22,42,62)'],['6×16=96; add16×4=64 for 160 weights; add16+4 biases for 180 parameters.','112 already includes hidden biases;180 includes all biases, so neither is a weights-only count.','This counts only the input-to-hidden layer and its biases, omitting output-layer parameters.','These use additions of neuron counts instead of products for fully connected weights.'],[C(41,'Week 9 Q6, network sizes and highlighted B96 explanation','6 inputs,16 hidden neurons,4 outputs; input-to-hidden weights6×16=96, excluding biases and hidden-output weights.','equation')],'Each pair of neurons in adjacent fully connected layers contributes a weight; biases are a separate per-output-unit count.',steps=['Input→hidden:6×16=96 weights.','Hidden→output:16×4=64 weights, total 160.','Biases:16+4=20; total trainable parameters 180.'],formulas=[F('W_ih=n_i n_h; W_total=n_i n_h+n_h n_o; P_total=W_total+n_h+n_o',{'W_ih':('input-to-hidden weight count','parameters'),'W_total':('all interlayer weight count','parameters'),'P_total':('weights plus biases','parameters'),'n_i':('input feature count','features'),'n_h':('hidden unit count','neurons'),'n_o':('output unit count','neurons')},['Two fully connected affine layers; one bias per hidden/output unit; no shared weights.'])],qtype='numerical',angles=['layer_scope','weights_vs_biases','full_network_count']))
qs.append(Q(9,7,7,'Gaussian motion prediction','A 2-D position belief is Gaussian with μ=(2,2) m and Σ=diag(0.25,0.16) m². Apply deterministic displacement u=(2,1) m with F=G=I and independent zero-mean Gaussian additive motion noise V=diag(0.5,0.4) m². What is the predicted mean and covariance?', ['μ̄=(4,3) m; Σ̄=diag(0.75,0.56) m².','μ̄=(4,3) m; Σ̄=diag(0.5,0.4) m².','μ̄=(2,2) m; Σ̄=diag(0.75,0.56) m².','μ̄=(4,3) m; Σ̄=diag(0.25,0.16) m².'],['The deterministic displacement adds to the mean and independent motion covariance adds to prior covariance.','This discards the existing uncertainty and retains only the newly added motion noise.','The covariance addition is correct but the deterministic displacement is omitted from the mean.','The mean is correct but the independent motion-noise covariance is omitted.'],[C(41,'Week 9 Q7, initial mean/covariance, displacement, noise and identity matrices','μ0=[2,2]ᵀ; Σ0=diag(.25,.16); u=[2,1]ᵀ; V=diag(.5,.4); F=G=I.','equation'),C(42,'Week 9 Q7 continuation, predicted mean and covariance sums','μ̄=[4,3]ᵀ; Σ̄=diag(.75,.56).','equation')],'Prediction moves the center while increasing uncertainty by the independent noise covariance; this is not a measurement correction.',assumptions=['All position components in the same Cartesian frame; supplied metre units; deterministic control; independent additive Gaussian noise.'],steps=['μ̄=Iμ+Iu=(2,2)+(2,1)=(4,3) m.','Σ̄=IΣIᵀ+V=diag(.25+.5,.16+.4)=diag(.75,.56) m².','Gaussian affine propagation gives the Gaussian belief with these parameters.'],formulas=[F('μ̄=Fμ+Gu; Σ̄=FΣFᵀ+V',{'μ̄':('predicted position mean','m per component'),'μ':('prior position mean','m per component'),'u':('known displacement control','m per component'),'F':('state-transition matrix,I₂','dimensionless'),'G':('control mapping,I₂','dimensionless'),'Σ̄':('predicted covariance','m² per entry'),'Σ':('prior covariance','m² per entry'),'V':('independent additive process covariance','m² per entry')},['Zero-mean independent additive Gaussian process noise; common Cartesian frame.'])],qtype='numerical',angles=['mean_and_covariance','independent_noise','prediction_vs_update']))
qs.append(Q(9,8,8,'State Markov assumption and belief history','For a sufficient state xₜ, observations zₜ and controls uₜ, the source states p(xₜ|x₀:ₜ₋₁,z₁:ₜ₋₁,u₁:ₜ)=p(xₜ|xₜ₋₁,uₜ). Which interpretation is correct?', ['Given the previous state and current control, earlier history adds no transition information; the estimated belief can still depend on past observations.','The latest observation zₜ₋₁ can always replace the previous state xₜ₋₁ in the transition model.','The current control uₜ alone determines the next-state distribution, independently of the previous state.','Past observations must be discarded from the state belief because the transition model is Markov.'],['The conditional independence concerns a sufficient true/model state, not an instruction to erase information used to estimate that state.','An observation can be noisy or partial; the stated assumption conditions on the state, not observation alone.','The right side explicitly retains xₜ₋₁ as well as uₜ.','Filtering summarizes observation history in a belief; Markov transitions do not eliminate that information.'],[C(42,'Week 9 Q8, full conditional Markov equality and explanation','p(x_t|x_0:t−1,z_1:t−1,u_1:t)=p(x_t|x_t−1,u_t); present state depends only on previous state and current control.','equation')],'A Markov transition model reduces conditional dependence after the previous state is specified. The state’s estimated distribution may still summarize a long observation history.',assumptions=['x is a sufficient state for the stated controlled model; equality is a modeling assumption, not a claim that every chosen feature vector is Markov.'],formulas=[F('p(xₜ|x₀:ₜ₋₁,z₁:ₜ₋₁,u₁:ₜ)=p(xₜ|xₜ₋₁,uₜ)',{'p':('conditional probability mass or density','probability mass dimensionless; density inverse state-volume units'),'xₜ':('state at time index t','model-defined state units'),'x₀:ₜ₋₁':('state history before t','same component units as x'),'z₁:ₜ₋₁':('past observation sequence','sensor-specific units'),'u₁:ₜ':('control history through t','control-specific units'),'xₜ₋₁':('immediately preceding state','same component units as x'),'uₜ':('current control','control-specific units')},['Controlled first-order Markov model with sufficient state.'])],angles=['conditional_independence','state_vs_observation','belief_history']))
qs.append(Q(9,9,9,'Augmented SLAM dimensions','A planar EKF-SLAM state contains robot pose (xᵥ,yᵥ,θᵥ) and M=6 landmarks, each with two coordinates. What are the dimensions of the state column, full covariance, and robot-to-map cross-covariance block, respectively?', ['15×1; 15×15; 3×12.','12×1; 12×12; 3×12.','15×1; 15×15; 12×3.','21×1; 21×21; 3×18.'],['Three pose variables plus 12 map coordinates give 15; the robot-to-map block has 3 robot rows and 12 map columns.','This leaves the three robot pose coordinates out of the augmented state.','The state and full covariance are correct, but12×3 is the transpose map-to-robot block.','This assigns three coordinates per planar landmark rather than the specified two.'],[C(42,'Week 9 Q9, robot/landmark coordinate counts and covariance dimensions','Robot pose has3 variables;6 landmarks contribute2 each; state15×1 and covariance15×15.','equation')],'State dimension determines both covariance axes; block orientation follows which variables index its rows and columns.',assumptions=['Planar point landmarks; state order robot pose first, then all landmark coordinate pairs.'],steps=['Map dimension2M=12.','Full dimension n=3+12=15.','A state column is 15×1; full covariance 15×15; robot-to-map block 3×12.'],formulas=[F('n=3+2M; dim(μ)=n×1; dim(Σ)=n×n; dim(Σᵥₘ)=3×(2M)',{'n':('augmented scalar state dimension','variables'),'M':('planar landmark count','landmarks'),'μ':('augmented mean column','position components m; heading rad'),'Σ':('full covariance','entry ij has units of state_i × state_j'),'Σᵥₘ':('robot-row/map-column covariance block','position-position m²; heading-position rad·m')},['Three planar robot pose variables and two position coordinates per landmark.'])],qtype='numerical',angles=['state_dimension','full_covariance','cross_block_orientation']))
qs.append(Q(9,10,10,'EKF heading-to-position covariance','Use augmented order (x,y,θ,mₓ,mᵧ), with positions in m and θ in rad. Initially μ=(2,1,0,5,4), robot covariance diag(0.04,0.04,0.01), map covariance diag(0.09,0.09), and robot-map cross block zero. The robot moves d=2 m using x′=x+d cosθ, y′=y+d sinθ, θ′=θ. Landmarks remain static. Add independent robot-coordinate noise diag(0.01,0.01,0.0025) after Jacobian propagation, with zero map noise. Which predicted robot covariance and map covariance are correct? (Position variances use m², heading variance rad², position-heading entries m·rad.)', ['Robot [[0.05,0,0],[0,0.09,0.02],[0,0.02,0.0125]]; map diag(0.09,0.09).','Robot diag(0.05,0.05,0.0125); map diag(0.09,0.09).','Robot [[0.05,0,0],[0,0.06,0.01],[0,0.01,0.0125]]; map diag(0.09,0.09).','Robot [[0.05,0,0],[0,0.09,0.02],[0,0.02,0.0125]]; map diag(0.10,0.10).'],['At θ=0, ∂y′/∂θ=2, adding4×0.01 to y variance and2×0.01 to its heading covariance; static map covariance is unchanged.','This replaces the motion Jacobian with identity and loses propagation of heading uncertainty into lateral position.','These entries correspond to using a unit displacement derivative instead of the stated d=2.','The robot block is right, but this injects robot process noise into the explicitly static, zero-process-noise landmark block.'],[C(43,'Week 9 Q10, robot/map means, initial block covariances and motion noise','Robot[2,1,0]ᵀ; map[5,4]ᵀ; Σvv=diag(.04,.04,.01),Σmm=diag(.09,.09),Σvm=0; displacement2m,V=diag(.01,.01,.0025).','equation'),C(44,'Week 9 Q10 derivation, motion model, robot and augmented Jacobians, covariance blocks','J_robot=[[1,0,0],[0,1,2],[0,0,1]] at θ=0; mean[4,1,0,5,4]; predicted robot block[[.05,0,0],[0,.09,.02],[0,.02,.0125]], map unchanged and cross block zero.','derivation')],'Even at zero mean heading, heading uncertainty propagates into lateral uncertainty. Static landmarks do not translate with the robot during prediction.',assumptions=['First-order EKF covariance propagation; independent additive noise already expressed in robot pose coordinates; static landmark model; zero initial robot-map cross covariance.'],steps=['Mean becomes (4,1,0,5,4): only robot x moves.','At θ=0 and d=2, J_robot=[[1,0,0],[0,1,2],[0,0,1]].','Robot variance x:0.04+0.01=0.05; y:0.04+4×0.01+0.01=0.09; θ:0.01+0.0025=0.0125.','Cov(y,θ)=2×0.01=0.02 and Cov(x,θ)=0.','The augmented Jacobian is blockdiag(J_robot,I₂); zero robot-map cross covariance remains zero and map covariance stays diag(.09,.09).'],formulas=[F('μ̄=(x+d cosθ,y+d sinθ,θ,mₓ,mᵧ); Jᵥ=[[1,0,−d sinθ],[0,1,d cosθ],[0,0,1]]; J=blockdiag(Jᵥ,I₂); Σ̄=JΣJᵀ+blockdiag(V,0₂)',{'μ̄':('predicted augmented mean','positions m; heading rad'),'x':('initial robot horizontal position','m'),'y':('initial robot vertical position','m'),'θ':('robot heading','rad'),'d':('forward displacement','m'),'mₓ':('static landmark horizontal coordinate','m'),'mᵧ':('static landmark vertical coordinate','m'),'Jᵥ':('robot motion Jacobian','entry ij has units state_i/state_j'),'J':('augmented motion Jacobian','entry ij has units state_i/state_j'),'I₂':('2×2 identity for static landmark','dimensionless'),'Σ':('initial augmented covariance','entry ij units state_i×state_j'),'Σ̄':('predicted augmented covariance','entry ij units state_i×state_j'),'V':('independent additive robot process covariance','diag entries m²,m²,rad²'),'0₂':('zero 2×2 landmark process covariance','m²')},['Linearize at the prior mean; additive state-coordinate noise independent of initial state; landmark does not move.'])],qtype='numerical',difficulty='medium',angles=['full_mean','Jacobian_derivation','heading_position_coupling','static_map','cross_covariance']))
notes=[(39,'1','Viewed crossover parents, all3 child equations and under-specified fitness ranking; binary-code mapping endpoints and D42 highlighted. Coordinate magnitude is not generally fitness.'),(40,'2','Viewed every cell in6×6 grid: S(0,0),W1(0,1),W2(2,4),G(5,5),six obstacles; all four fraction options1/24,1/45,1/55,1/65. Read horizontal-first counts and vertical-first conceptual explanation.'),(41,'3','Viewed sequence architecture options; Q6 clearly highlights(B)96, correcting frozen handoff originalPrintedKey6 as a transcription defect only; Q7 initial mean,covariance,noise,control and first3 Gaussian options.'),(42,'4','Viewed last Q7 option and complete mean/covariance sums; Q8 all four conditional expressions and highlighted Markov equality; Q9 all state/covariance choices and3+12 dimensional reasoning.'),(43,'5','Viewed Q10 all initial robot/map quantities, zero cross block, d2m and noise; read all four full mean/robot/map covariance options. Highlighted B includes y variance.09 and y-heading.02.'),(44,'6','Viewed Q10 complete motion model and derivative Jacobian, augmented5×5 matrix, exact covariance multiplication, zero3×2 cross block, unchanged map covariance and END.')]
